mapper.update:
UPDATE community_post
SET post_image_url = #{postImageUrl}
WHERE id = #{postId}
AND is_deleted = 0

UPDATE community_post
SET is_deleted = 1,
deleted_at = NOW()
WHERE id = #{postId}
AND user_id = #{userId}
AND is_deleted = 0

UPDATE community_post
SET like_count = like_count + #{delta}
WHERE id = #{postId}
AND is_deleted = 0

UPDATE community_post
SET comment_count = comment_count + #{delta}
WHERE id = #{postId}
AND is_deleted = 0

mapper.select:
SELECT DISTINCT p.* FROM community_post p
JOIN community_post_tag pt ON p.id = pt.post_id JOIN community_tag t ON pt.tag_id = t.id
WHERE p.is_deleted = 0
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.category = #{category}
AND t.name = #{tag}
ORDER BY p.created_at DESC
ORDER BY p.created_at ASC
ORDER BY p.like_count DESC, p.view_count DESC, p.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT p.id) FROM community_post p
JOIN community_post_tag pt ON p.id = pt.post_id JOIN community_tag t ON pt.tag_id = t.id
WHERE p.is_deleted = 0
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.category = #{category}
AND t.name = #{tag}

SELECT *
FROM community_post
WHERE user_id = #{userId}
AND is_deleted = 0
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}
